  [260784] = { "Con le linguette di marca SAF-T regalare dinamite a tutti i tuoi amici è proprio SAF!", 0x98f5345b, "u" },
  [260792] = { "Infligge $N1 danni da fuoco in un raggio di $N2 m.\nFacile da lanciare, e pure SAF-T!", 0x03ef7ef0, "u" },
  [260793] = { "Infligge $N1 danni da fuoco e stordisce i bersagli in un raggio di $N2 m per $D1. Qualsiasi danno interrompe l'effetto.\nLe bombe di marca SAF-T non ti esplodono *quasi* mai in mano (o tra le zampe!).", 0x9d043dfd, "u" },
  [260795] = { "Infligge $N1 danni da fuoco e stordisce i bersagli in un raggio di $N2 m per $D1. Qualsiasi danno interrompe l'effetto.", 0x109f3d47, "u" },
  [260796] = { "L'imbottitura SAF-T previene quei banali incidenti durante il lancio.", 0xee6bfa8f, "u" },
  [260797] = { "Infligge $N1 danni da fuoco e stordisce i bersagli in un raggio di $N2 m per $D1. Qualsiasi danno interrompe l'effetto.", 0x1f15bb8e, "u" },
  [260798] = { "Infligge $N1 danni da fuoco in un raggio di $N2 m.\nSe è facile da lanciare, non è SAF-T!", 0xf2c5be9b, "u" },
  [260799] = { "Sai dov'è la tua pecora?! SAF-T lo sa.", 0xc32aa110, "u" },
  [260800] = { "Evoca una ⟦Explosive Sheep=Pecora Esplosiva⟧ che carica un nemico vicino ed esplode, infliggendo $N1 danni. Dura $D1 o finché non esplode.\nGarantito: esplode solo dove è SAF!", 0x8630c130, "u" },
  [260801] = { "Garantito: non brucia!", 0xa4ec5a4b, "u" },
  [260802] = { "Infligge $N1 danni da fuoco e stordisce i bersagli in un raggio di $N2 m per $D1. Qualsiasi danno interrompe l'effetto.\nThro mo mo tar!", 0x4f16c3c9, "u" },
  [260803] = { "Infligge $N1 danni da fuoco in un raggio di $N2 m.\nChi ha bisogno di sicurezza, quando è così facile da lanciare?", 0x6076ad34, "u" },
  [260804] = { "Imbottitura extra per essere SAF-T!", 0x2c48d420, "u" },
  [260805] = { "Infligge $N1 danni da fuoco e stordisce i bersagli in un raggio di $N2 m per $D1. Qualsiasi danno interrompe l'effetto.\nS. A. F. T. B. O. M. B. A. SAF-T. Bomba.", 0xebf1711d, "u" },
  [260806] = { "Conferisce l'invisibilità per $D1.\nSAF-T vuol dire non farsi beccare.", 0x64ccf8e1, "u" },
  [260807] = { "Piazza un Compact Critter Carrier per $D1 che permette ai Cacciatori del tuo gruppo di accedere ai famigli nella stalla.", 0xfe7715de, "u" },
  [260808] = { "EZ da usare, e non fa quasi mai cilecca!", 0xbd2ae103, "u" },
  [260809] = { "Infligge $N1 danni da fuoco e stordisce i bersagli in un raggio di $N2 m per $D1. Qualsiasi danno interrompe l'effetto.\nIl Tru-Trigger fa a pezzi i nemici, non le tue mani.", 0xd4f89e18, "u" },
  [260810] = { "Riduce la velocità di caduta per $D1.\nSAF-T, nel caso tu debba saltare.", 0xbe09a553, "u" },
  [260811] = { "C'è di tutto: una chiave fissa, una chiave inglese, un martello... persino un piccone.", 0x46133832, "u" },
  [260812] = { "Recupera il bottino da un cadavere vicino.", 0xeb0158d6, "u" },
  [260813] = { "Previene l'esposizione accidentale all'ossigeno. Non sarebbe SAF.", 0xcaa28cbf, "u" },
  [260814] = { "Infligge $N1 danni da fuoco in un raggio di $N2 m.\nLa SAF-T non è tonta. È furba!", 0x6f0df3ed, "u" },
  [260815] = { "Racchiudi i tuoi esplosivi in involucri EZ-Thro placcati di torio, facili da lanciare.", 0xb5bfed55, "u" },
  [260816] = { "Infligge $N1 danni da fuoco e stordisce i bersagli per $D1 in un raggio di $N3 m. Qualsiasi danno interrompe l'effetto.\nCon EZ-Thro chiunque può usare le granate!", 0x759cf92a, "u" },
  [260817] = { "Infligge $N1 danni da fuoco e stordisce i bersagli in un raggio di $N2 m per $D1. Qualsiasi danno interrompe l'effetto.\nCosì EZ che puoi lanciarla persino al buio.", 0x61cf766f, "u" },
  [260818] = { "Brucia $N1 mana a chi si trova nel raggio dell'esplosione e infligge al bersaglio danni pari al $N2% del mana prosciugato. Inoltre silenzia i bersagli colpiti dall'esplosione per $D1.", 0xd08b8999, "u" },
  [260819] = { "Trasportati in tutta sicurezza a ⟦Gadgetzan=Meccania⟧ a Tanaris! SI-CU-REZ-ZA! Intesi? Non accadrà nulla di male usando questo gioiello.", 0xa6aec356, "u" },
  [260820] = { "Squarcia i piani dimensionali e ti teletrasporta a ⟦Everlook=Lungavista⟧ nella regione di ⟦Winterspring=Fontefredda⟧. Potrebbero verificarsi problemi tecnici, ma è proprio questo il bello dell'⟦Goblin Engineering=Ingegneria dei Goblin⟧!", 0xe4f8b06f, "u" },
  [260821] = { "Squarcia i piani dimensionali e ti teletrasporta a Kaylaena's Workshop sul ⟦Mount Hyjal=Monte Hyjal⟧. Con questa folle combinazione di ingegneria dei goblin e degli gnomi è molto probabile che si verifichino problemi tecnici.\nNon solo unisce la tecnologia dei goblin e degli gnomi, ma combina anche i progetti delle compagnie EZ-Thro e SAF-T. Chissà se funzionerà davvero?", 0x4c55dbf7, "u" },
  [260822] = { "Ripristina $N1 cariche di un dispositivo di marca SAF-T o EZ-Thro in tuo possesso che non preveda esplosioni. Con gli esplosivi sarebbe del tutto non-SAF.", 0x848cf013, "u" },
  [260823] = { "Squarcia i piani dimensionali e ti teletrasporta a Kaylaena's Workshop sul ⟦Mount Hyjal=Monte Hyjal⟧. Con questa folle combinazione di ingegneria dei goblin e degli gnomi è molto probabile che si verifichino problemi tecnici.\nUna pericolosa fusione delle tecniche d'ingegneria dei goblin e degli gnomi.", 0xa3c2df84, "u" },
  [260824] = { "Trasforma il bersaglio in un pollo per $D1. Sempre che la polarità della trasmogrificazione non sia stata invertita...", 0x4ecdd5b2, "u" },
  [260825] = { "Plana verso il basso per $D1, controllando la direzione di volo.", 0x0e9703cc, "u" },
  [260827] = { "Avvolge l'utilizzatore in un campo di occultamento per un massimo di $D1. Non può essere usato in combattimento. Dopo che ti muovi, il campo persiste per un massimo di $D2.\nUsato dai veri agenti segreti.", 0xfc7d7a88, "u" },
  [260828] = { "Attiva una serie di propulsori che aumentano la velocità di movimento fino al $N1%, per un massimo di $D1.\nSfreccia in salvo con SAF-T.", 0x24b3dfe7, "u" },
  [260829] = { "Altera un campo magnetico tra te e il nemico vicino che hai come bersaglio, respingendovi a vicenda.\n\nInfluenza solo bersagli fino a $N1 livelli superiori al tuo. Alcuni bersagli non possono essere spostati. Un bersaglio può subire questo effetto solo una volta ogni $D1.\nLa compagnia EZ-Thro declina ogni responsabilità se i magneti impediscono il lancio delle granate.", 0x7c2a433a, "u" },
  [260830] = { "Ti teletrasporta in avanti di $N1 m.\nTeletrasportati in salvo con SAF-T!", 0xdf16b971, "u" },
  [260880] = { "Il globo luminoso sembra guardarti e seguire i tuoi movimenti con silenziosa curiosità.", 0x0b957eb6, "u" },
  [260881] = { "La superficie di questo oggetto è liscia al tatto e, quando lo tieni in mano, ti fa rizzare i peli sulla nuca.", 0xa785cc82, "u" },
  [260883] = { "Questo oggetto vibra piano, in un costante stato di moto perpetuo. Se provi a tenerlo fermo, la forza che esercita aumenta moltissimo d'intensità.", 0x81e5fb2d, "u" },
})
